14	    setCopied(true);
15	    setTimeout(() => setCopied(false), 2000);
16	  };
17	  return (
18	    <button
19	      onClick={handleCopy}
20	      className={cn(
21	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-[10px] font-medium border transition-all",
22	        copied
23	          ? "bg-green-50 text-green-600 border-green-200"
