101	      list = list.filter((s) => s.status === statusFilter);
102	    }
103	
104	    // Score filter
105	    if (scoreFilter !== "all") {
106	      list = list.filter((s) => {
107	        if (s.overall_score === null) return false;
108	        if (scoreFilter === "poor") return s.overall_score < 40;
109	        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
110	        if (scoreFilter === "good") return s.overall_score >= 70;
111	        return true;
112	      });
113	    }
114	
115	    // Sort
116	    list.sort((a, b) => {
117	      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
118	      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
119	      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
120	      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
